/**
 * Repo documentation manifest shape (design spec §5.2). `docs/manifest.json`
 * is generated by `docaudit compile` from every doc's frontmatter; it is the
 * one file an agent must load (after `AGENTS.md`) to navigate the doc store
 * — see design spec §7.1. Never hand-edited; a CI check fails if the
 * manifest on disk doesn't match a fresh compile (design spec §12).
 *
 * The published JSON Schema for this shape lives at
 * `schemas/manifest.schema.json`.
 */

import type { Confidence, DocKind, DocStatus } from "./frontmatter.js";

/** One entry in `Manifest.subsystems`, keyed by subsystem name. */
export interface ManifestSubsystem {
	/** Doc ids of this subsystem's canon shards. */
	canon: string[];
	/** Doc ids of this subsystem's runbooks. */
	runbooks: string[];
	/** Doc ids of this subsystem's ADRs. */
	adrs: string[];
	/**
	 * CANONICAL — repo-root-relative POSIX path prefixes (no leading "./")
	 * that make up this subsystem's code, e.g. `"src/session/"`. Not
	 * picomatch globs — these are directory roots used for subsystem-level
	 * grouping, distinct from a doc's `covers` globs.
	 */
	code_roots: string[];
	owner: string;
}

/** One entry in `Manifest.docs`, keyed by doc id. A compiled projection of that doc's frontmatter, plus derived fields. */
export interface ManifestDocEntry {
	/** Repo-root-relative POSIX path to the doc's Markdown file (no leading "./"). */
	path: string;
	kind: DocKind;
	status: DocStatus;
	confidence: Confidence;
	/** Estimated token cost of loading this shard's body — lets an agent budget context before loading (design spec §5.2). */
	tokens_estimate: number;
	tags: string[];
	/**
	 * CANONICAL — same picomatch-against-repo-root-relative-POSIX-paths
	 * semantics as `DocFrontmatter.covers` (see `frontmatter.ts`); this is a
	 * direct copy of that field into the compiled manifest, not a
	 * re-derivation.
	 */
	covers: string[];
}

/**
 * One route: maps a set of code paths to the doc ids an agent should load
 * before touching matching files (design spec §5.2, §7.3, §11.3).
 */
export interface ManifestRoute {
	/** CANONICAL — picomatch glob matched against repo-root-relative POSIX paths (no leading "./"), same convention as `covers`. */
	match: string;
	/** Doc ids to load when a touched file matches `match`. */
	load: string[];
	/**
	 * §7.3/§11.3 — when `true`, a PR touching a matching path must either
	 * re-verify every doc in `load` or carry a `docs-deferred` label; the PR
	 * bot enforces the choice. Absent or `false` means the route is
	 * informational only. Defaults to `false` when omitted.
	 */
	required?: boolean;
}

/**
 * A doc/code disagreement an agent reported during a task (design spec
 * §7.4). Lands in `Manifest.conflicts` via the PR bot until the doc is
 * fixed as its own change.
 */
export interface ManifestConflict {
	/** The doc id whose claim was found to disagree with code. */
	docId: string;
	/** The specific claim text (or a short paraphrase) that disagreed with observed reality. */
	claim: string;
	/** What the agent actually observed in code. */
	observed: string;
	/** `path:line` (repo-root-relative POSIX path) where the disagreement was observed. */
	location: string;
}

/**
 * `docs/manifest.json` — generated, versioned, and the only file (besides
 * `AGENTS.md`) an agent must load to know every subsystem, owner, canonical
 * doc, and the trust rules (design spec §5.2, Example 3 in §14).
 */
export interface Manifest {
	version: number;
	/** Commit SHA this manifest was compiled at. Compared against HEAD to detect a stale/neglected system (design spec §11.5). */
	generated_at_sha: string;
	/** Embedded copy of the §7.2 trust rules, so an agent that loads only the manifest still gets them. */
	trust_rules_digest: string;
	/** Repo-root-relative path to the agent entrypoint file (normally `"AGENTS.md"`). */
	entrypoint: string;
	subsystems: Record<string, ManifestSubsystem>;
	/** Keyed by doc id. */
	docs: Record<string, ManifestDocEntry>;
	routes: ManifestRoute[];
	/** Keyed by packet name (e.g. `"modify-api"`); value is the ordered list of doc ids in that packet (design spec §7.3). */
	context_packets: Record<string, string[]>;
	/** Doc ids currently in the stale queue (design spec §13 — the doc steward's whole job). */
	stale_queue: string[];
	conflicts: ManifestConflict[];
}
